    "quickstart.activateTitle": "Активируйте аккаунт Platho",
    "quickstart.activateWhy": "Активация регистрирует ваши ключи для сообщений в блокчейне (разовая комиссия из кошелька). После неё можно отправлять и получать приватные сообщения. Нужен пополненный кошелёк — сделайте это сейчас или позже на вкладке «Профиль».",
    "quickstart.activationNeedsChecking": "Для активации нужно {fee} GRAM · проверка баланса…",
    "quickstart.addKeyTitle": "Добавьте ключ TON Center",
    "quickstart.addKeyWhy": "Ваш собственный бесплатный API-ключ TON Center (10 запросов/сек + индексатор сообщений) ускоряет Platho и снимает общие ограничения по частоте. Необязательно — без него Platho работает по бесключевому пути toncenter, просто медленнее. Получите ключ за ~10 секунд у Telegram-бота @toncenter и вставьте его сюда.",
    "quickstart.backToTopUp": "Назад к пополнению",
    "quickstart.backupKeyTitle": "Сохраните ключ кошелька",
    "quickstart.backupKeyWhy": "Хранилище браузера можно очистить — особенно в Safari на iPhone — что сотрёт кошелёк с этого устройства. Сохраните зашифрованный файл ключа кошелька сейчас; он защищён вашим паролем и также содержит ваш ключ TON Center, так что вы сможете восстановить всё на любом устройстве.",
    "quickstart.balanceActivationNeeds": "Баланс кошелька: {balance} GRAM · для активации нужно {fee} GRAM",
