    "quickstart.activateAction": "Activer le compte",
    "quickstart.activateTitle": "Activez votre compte Platho",
    "quickstart.activateWhy": "L'activation enregistre vos clés de messagerie on-chain (des frais uniques depuis votre portefeuille). Ensuite, vous pouvez envoyer et recevoir des messages privés. Elle nécessite un portefeuille approvisionné - faites-le maintenant, ou plus tard depuis l'onglet Profil.",
    "quickstart.activationNeedsChecking": "L'activation nécessite {fee} GRAM · vérification du solde…",
    "quickstart.addKeyTitle": "Ajouter une clé TON Center",
    "quickstart.addKeyWhy": "Votre propre clé API TON Center gratuite (10 requêtes/s + l'indexeur de messages) rend Platho plus rapide et évite les limites de débit partagées. Facultative - sans elle, Platho fonctionne sur le chemin toncenter sans clé, juste plus lentement. Obtenez-en une en ~10 secondes depuis le bot Telegram @toncenter, puis collez-la ici.",
    "quickstart.backToTopUp": "Retour à l'approvisionnement",
    "quickstart.backupKeyTitle": "Sauvegardez la clé de votre portefeuille",
    "quickstart.backupKeyWhy": "Le stockage du navigateur peut être effacé - surtout sur iPhone Safari - ce qui effacerait votre portefeuille de cet appareil. Enregistrez maintenant le fichier de clé de portefeuille chiffré ; il est protégé par votre mot de passe et contient aussi votre clé TON Center, ce qui vous permet de tout restaurer sur n'importe quel appareil.",
    "quickstart.balanceActivationNeeds": "Solde du portefeuille : {balance} GRAM · l'activation nécessite {fee} GRAM",
