    "quickstart.notCompleted": "Non terminé - réessayez.",
    "quickstart.notEnoughGramHint": "Pas assez de GRAM pour activer — approvisionnez d'abord, puis vérifiez à nouveau.",
    "quickstart.notEnoughToActivate": "Pas assez de GRAM ({balance}) — l'activation nécessite {fee}. Utilisez « Retour à l'approvisionnement », approvisionnez le portefeuille, puis vérifiez à nouveau.",
    "quickstart.nothingEntered": "Rien saisi - collez une clé ou Passez.",
    "quickstart.pasteKeyPlaceholder": "Collez votre clé API TON Center",
    "quickstart.pitch": "Vos clés et vos messages n'existent que sur cet appareil, chiffrés — il n'y a aucun compte serveur qui puisse les lire ni détenir vos clés. Les chats privés sont chiffrés de bout en bout et post-quantique ; tout est client-direct sur TON, sans passerelle centrale à bloquer ou censurer.",
