    "quickstart.addKeyWhy": "Ihr eigener kostenloser TON Center API-Schlüssel (10 Anfragen/Sek. + der Nachrichten-Indexer) macht Platho schneller und vermeidet gemeinsame Ratenlimits. Optional – ohne ihn läuft Platho auf dem schlüssellosen toncenter-Pfad, nur langsamer. Holen Sie sich einen in ~10 Sekunden vom @toncenter-Telegram-Bot und fügen Sie ihn hier ein.",
